import java.io.*;
import java.util.*;

public class Main {
    static abstract class Employee { abstract long pay(); }
    static class Full extends Employee {
        long s; Full(long s) { this.s = s; }
        long pay() { return s + s / 10; }
    }
    static class Part extends Employee {
        long h, r; Part(long h, long r) { this.h = h; this.r = r; }
        long pay() { return h * r + (h > 40 ? (h - 40) * r / 2 : 0); }
    }
    static class Contract extends Employee {
        long d, r; Contract(long d, long r) { this.d = d; this.r = r; }
        long pay() { return d * r; }
    }
    static class Intern extends Employee { long pay() { return 500; } }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        List<Employee> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] p = br.readLine().trim().split("\\s+");
            if (p[0].equals("FULL")) list.add(new Full(Long.parseLong(p[1])));
            else if (p[0].equals("PART")) list.add(new Part(Long.parseLong(p[1]), Long.parseLong(p[2])));
            else if (p[0].equals("CONTRACT")) list.add(new Contract(Long.parseLong(p[1]), Long.parseLong(p[2])));
            else list.add(new Intern());
        }
        long total = 0;
        for (Employee e : list) { System.out.println(e.pay()); total += e.pay(); }
        System.out.println("TOTAL " + total);
    }
}

