public class Main {
    static class Ticket {
        int cost(int qty) { return 10 * qty; }
    }
    static class Premium extends Ticket {
        @Override
        int cost(int qty) { return 15 * qty; }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int total = 0;
        for (int i = 0; i < n; i++) {
            String type = in.next();
            int qty = in.nextInt();
            Ticket t = type.equals("P") ? new Premium() : new Ticket();
            total += t.cost(qty);
        }
        System.out.println(total);
    }
}
